INSERT INTO feature VALUES('std-llvm','modules','The module std.llvm','packages','partial','ordinary',NULL,'`std.llvm` gives the fragment of the `llvm` dialect of MLIR that `std` admits as one `theory` block `Llvm`, with 6 sorts and 63 operations: a value has its type as an index, an attribute is an input port of a sort of constants or of `Integer` or `String`, and the rest of a body is a port of the sort `Body`; the block checks with no rule and no model, and a constant of a sort is a value of `Terms Llvm` at that sort, which a `match` reads; a term of `Body` or of `Val` is refused as a type.',NULL,'library/std/src/llvm.gandr corpus/model/desc/llvm-constants-are-terms.gandr','corpus/model/desc/llvm-constants-are-terms.gandr','#4150');
